  getInvestedStocksData() {
    const strategyKeys = [
      AppConstants.stocksStrategyNum,
      AppConstants.stocksStrategyNumExtra
    ];

    let allTrades: any[] = [];

    // Collect trades from both strategies
    strategyKeys.forEach(strategy => {
      const data = JSON.parse(localStorage.getItem('curr_positions' + strategy));
      if (data && data.trades) {
        allTrades = allTrades.concat(data.trades);
      }
    });

    let i = 0;

    if (allTrades.length) {
      allTrades.forEach((pos, index) => {
        i++;
        setTimeout(() => {
          let e1 = new Instrument();
          e1.tradingSymbol = pos.scrip;
          this.fetchChartData(e1);

          if (index === allTrades.length - 1) {
            console.log('All chart data fetches have been triggered.');
            AppConstants.miscEvent$.next('investedStocksFetched');
          }
        }, i * 200);
      });
    }

    // Always fetch NIFTY separately
    let e2 = new Instrument();
    e2.tradingSymbol = 'NIFTY 50';
    this.fetchChartData(e2);
  }

  fetchChartData(object) {
  
    let stock: MasterInstrument = this.findStockInMasters(object);

    // console.log('fetchChartData element:', stock);
    // console.log('fetchChartData element:', stock.tradingSymbol, stock.token, stock.exchange);

    let today = new Date();
    let from_date_obj = new Date();
    //let today = new Date('2020-10-31');
    //let from_date_obj = new Date('2020-10-31');
    from_date_obj.setDate(from_date_obj.getDate() - StocksConstants.chartDayToFetch);
    let from_date = '' + from_date_obj.getFullYear() + '-' + ('0' + (from_date_obj.getMonth() + 1)).slice(-2) + '-' + ('0' + from_date_obj.getDate()).slice(-2);
    let to_date = '' + today.getFullYear() + '-' + ('0' + (today.getMonth() + 1)).slice(-2) + '-' + ('0' + today.getDate()).slice(-2);

    //console.log('fetchChartData dates:', from_date, to_date);

    if (stock && stock.token) {

      const headers = new HttpHeaders({
        'authorization': AppConstants.broker_auth,
      });
      let httpOptions = {
        responseType: 'json' as 'json',
        headers: headers
      };

      let url = 'https://kite.zerodha.com/oms/instruments/historical/' + stock.token + '/day?user_id=' + AppConstants.zerodhaUserId + '&oi=1&from=' + from_date + '&to=' + to_date;

      // return this.http.get(url, httpOptions);

      this.http.get(url, httpOptions).subscribe((res: any) => {
        AppConstants.requestStatusEvent$.next({'status': 'success', 'message': 'FETCHED ' + stock.tradingSymbol});
        console.log('fetchChartData data:', stock.tradingSymbol, res);
        if (res.data.candles) {
          let arr = res.data.candles;
          if (arr.length === 0) {
            console.log('ZERO CANDLES FOR ', stock.tradingSymbol);
          }
          for (let j = 0; j < arr.length; j++) {
            let element = arr[j];
              
            let obj = StocksConstants.candlesData[stock.tradingSymbol]; // getting all data for the stock
            if (!obj) {
              obj = {};
            }
            let d = this.getDateInFormat(element[0]);
            obj[d] = [ element[1], element[2], element[3], element[4], element[5], element[6] ];
  
            StocksConstants.candlesData[stock.tradingSymbol] = obj;
          }
        }
  
        console.log('candles:', Object.keys(StocksConstants.candlesData).length, StocksConstants.candlesData);
      });
    }
  }

  /*
  Zerodha names a monthly contract with a 3-letter month (NIFTY26AUG25000CE, NIFTY26AUGFUT) and a
  weekly one with a numeric date (NIFTY2682525000CE). So the tradingsymbol itself tells us which
  expiries are monthly - no "last expiry of the month" guessing, and the key we extract here is
  exactly the key MapService.getExpiry() needs to rebuild the same symbol.
  */
  collectMonthlyExpiry(name, tradingsymbol, expiry, stats) {

    let map = AppConstants.getMonthlyExpiryMap(name);
    if (!map || !expiry || !tradingsymbol || !tradingsymbol.startsWith(name)) {
      return;
    }

    let key = tradingsymbol.substring(name.length, name.length + 5); // NIFTY26AUG25000CE -> 26AUG
    if (!ZerodhaService.MONTHLY_EXPIRY_KEY.test(key)) {
      return; // weekly contract
    }

    let parts = expiry.split('-'); // 2026-08-25
    if (parts.length !== 3) {
      return;
    }

    /*
    Must be built at LOCAL midnight. MapService.isMonthlyExpiry() compares with getTime() against a
    date it has run setHours(0,0,0,0) on, and the hardcoded entries are new Date(y, m, d) - also
    local midnight. new Date('2026-08-25') would be UTC midnight and would never compare equal.
    */
    let expiryDate = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
    if (isNaN(expiryDate.getTime())) {
      return;
    }

    let existing = map[key];
    if (existing) {
      if (existing.getTime() !== expiryDate.getTime()) {
        stats.mismatched.add(name + ' ' + key + ': hardcoded ' + existing.toDateString() + ', masters says ' + expiryDate.toDateString());
        if (AppConstants.overwriteMonthlyExpiriesFromMasters) {
          map[key] = expiryDate;
        }
      }
      return; // never drop or silently change a hardcoded value
    }

    map[key] = expiryDate;
    stats.added.add(name + ' ' + key + ' = ' + expiryDate.toDateString());
  }

  reportMonthlyExpiries(stats) {

    if (stats.added.size) {
      console.log('Monthly expiries added from masters (' + stats.added.size + '):', Array.from(stats.added));
      AppConstants.requestStatusEvent$.next({ 'status': 'success', 'message': 'Added ' + stats.added.size + ' monthly expiries' });
    } else {
      console.log('Monthly expiries: nothing new to add');
    }

    if (stats.mismatched.size) {
      console.warn('Monthly expiry MISMATCH - hardcoded value kept, please correct application.constant.ts:', Array.from(stats.mismatched));
      AppConstants.requestStatusEvent$.next({ 'status': 'warning', 'message': stats.mismatched.size + ' monthly expiry mismatch(es) - see console' });
    }
  }

  getDateInFormat(str = null) {
    if (!str) {
      str = new Date();
    }
    let date = new Date(str);
    let d = date.getDate();
    let m = date.getMonth() + 1; //Month from 0 to 11
    let y = date.getFullYear();
    let h = 0; //date.getHours();
    let mins = 0; //date.getMinutes();
    let s = 0; //date.getSeconds();
    // dd-mm-yyyy hh:mm:ss
    let format = '' + (d <= 9 ? '0' + d : d) + '-' + (m <= 9 ? '0' + m : m) + '-' + y + ' ' + (h <= 9 ? '0' + h : h) + ':' + (mins <= 9 ? '0' + mins : mins) + ':' + (s <= 9 ? '0' + s : s);
    return format;
  }

