interface HiringTeamMember {
  name: string;
  profile_link: string;
}

interface ApplicantStats {
  total_applicants: string | null;
  recent_applicants: string | null;
}

interface Job {
  company_name: string;
  job_title: string;
  location: string;
  posted_time: string;
  applied: boolean;
  easy_apply: boolean;
  job_link: string;
  external_link: string | null;
  hiring_team: HiringTeamMember[];
  job_description: string;
  applicant_stats: ApplicantStats;
}

interface FilterChip {
  label: string;
  active: boolean;
  type: 'notApplied' | 'notEasyApply' | 'notClicked' | 'notApplicable' | 'sortByTime' | 'past24Hours' | 'location';
  value?: string;
}

@Component({
  selector: 'app-linkedin',
  standalone: true,
  imports: [FormsModule, CommonModule],
  templateUrl: './linkedin.component.html',
  styleUrls: ['./linkedin.component.scss']
})
export class linkedinComponent implements OnInit {

  constructor(
    private linkedinService: linkedinService,
  ) {
  }
  
  ngOnInit(): void {

  }

  allJobs: Job[] = [];
  filteredJobs: Job[] = [];
  selectedJob: Job | null = null;
  searchQuery: string = '';

  filterChips: FilterChip[] = [
    { label: 'Not Applied', active: true, type: 'notApplied' },
    { label: 'Not Easy Apply', active: false, type: 'notEasyApply' },
    { label: 'Not Clicked', active: false, type: 'notClicked' },
    { label: 'Hide Not Applicable', active: false, type: 'notApplicable' },
    { label: 'Sort by Time', active: false, type: 'sortByTime' },
    { label: 'Past 24 Hours', active: false, type: 'past24Hours' }
  ];

  locationChips: FilterChip[] = [
    { label: 'Germany', active: false, type: 'location', value: 'Germany' },
    { label: 'Spain', active: false, type: 'location', value: 'Spain' },
    { label: 'Denmark', active: false, type: 'location', value: 'Denmark' },
    { label: 'Netherlands', active: false, type: 'location', value: 'Netherlands' },
    { label: 'Austria', active: false, type: 'location', value: 'Austria' },
    { label: 'Dubai', active: false, type: 'location', value: 'Dubai' },
    { label: 'Sweden', active: false, type: 'location', value: 'Sweden' },
    { label: 'Finland', active: false, type: 'location', value: 'Finland' },
    { label: 'Singapore', active: false, type: 'location', value: 'Singapore' }
  ];

  onFileSelected(event: Event): void {
    const input = event.target as HTMLInputElement;
    if (!input.files || input.files.length === 0) return;

    const files = Array.from(input.files);
    let filesProcessed = 0;

    files.forEach(file => {
      const reader = new FileReader();
      reader.onload = (e) => {
        try {
          const content = e.target?.result as string;
          const data = JSON.parse(content);
          
          if (data.jobs && Array.isArray(data.jobs)) {
            this.allJobs = [...this.allJobs, ...data.jobs];
          }
        } catch (error) {
          console.error('Error parsing JSON file:', error);
        }

        filesProcessed++;
        if (filesProcessed === files.length) {
          this.applyFilters();
        }
      };
      reader.readAsText(file);
    });
  }

  openJobs(count: number): void {
    const jobsToOpen = count === -1 ? this.filteredJobs : this.filteredJobs.slice(0, count);
    
    jobsToOpen.forEach((job, index) => {
      // Add a small delay between opening tabs to avoid browser blocking
      setTimeout(() => {
        window.open(job.external_link, '_blank', 'noopener,noreferrer');
        
        // Mark as clicked if it has external link
        if (job.external_link) {
          const key = this.generateJobKey(job);
          const clickData = {
            jobTitle: job.job_title,
            companyName: job.company_name,
            location: job.location,
            clickedDate: new Date().toISOString()
          };
          localStorage.setItem(key, JSON.stringify(clickData));
        }
      }, index * 100); // 100ms delay between each tab
    });

    // Force update the view
    setTimeout(() => {
      this.filteredJobs = [...this.filteredJobs];
      if (this.selectedJob) {
        const jobIndex = this.filteredJobs.findIndex(j => j === this.selectedJob);
        if (jobIndex !== -1) {
          this.selectedJob = this.filteredJobs[jobIndex];
        }
      }
    }, jobsToOpen.length * 100 + 200);
  }

  exportLocalStorage(): void {
    const storageData: { [key: string]: string } = {};
    
    // Get all localStorage items
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key && (key.startsWith('job_') || key.startsWith('not_applicable_'))) {
        const value = localStorage.getItem(key);
        if (value) {
          storageData[key] = value;
        }
      }
    }
    
    // Create blob and download
    const dataStr = JSON.stringify(storageData, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    
    const link = document.createElement('a');
    link.href = url;
    link.download = `job-tracker-data-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }

  onImportFile(event: Event): void {
    const input = event.target as HTMLInputElement;
    if (!input.files || input.files.length === 0) return;

    const file = input.files[0];
    const reader = new FileReader();
    
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const data = JSON.parse(content);
        
        // Import all data to localStorage
        Object.keys(data).forEach(key => {
          localStorage.setItem(key, data[key]);
        });
        
        // Refresh the view
        this.applyFilters();
        alert('Data imported successfully!');
      } catch (error) {
        console.error('Error importing data:', error);
        alert('Error importing data. Please check the file format.');
      }
    };
    
    reader.readAsText(file);
    // Reset input so same file can be selected again
    input.value = '';
  }

  toggleFilter(chip: FilterChip): void {
    chip.active = !chip.active;
    this.applyFilters();
  }

  onSearchChange(event: Event): void {
    const input = event.target as HTMLInputElement;
    this.searchQuery = input.value;
    this.applyFilters();
  }

  getTotalJobsCount(): number {
    return this.allJobs.length;
  }

  getRemainingJobsCount(): number {
    return this.allJobs.filter(job => {
      // Exclude if applied
      if (job.applied) return false;
      
      // Exclude if easy apply
      if (job.easy_apply) return false;
      
      // Exclude if clicked (and has external link)
      if (job.external_link) {
        const clickKey = this.generateJobKey(job);
        if (localStorage.getItem(clickKey)) return false;
      }
      
      // Exclude if not applicable
      if (this.isNotApplicable(job)) return false;
      
      return true;
    }).length;
  }

  applyFilters(): void {
    let jobs = [...this.allJobs];

    // Apply search filter
    if (this.searchQuery.trim()) {
      const query = this.searchQuery.toLowerCase();
      jobs = jobs.filter(job => {
        return (
          job.job_title.toLowerCase().includes(query) ||
          job.company_name.toLowerCase().includes(query) ||
          job.location.toLowerCase().includes(query) ||
          job.posted_time.toLowerCase().includes(query) ||
          (job.job_description && job.job_description.toLowerCase().includes(query)) ||
          (job.external_link && job.external_link.toLowerCase().includes(query)) ||
          job.hiring_team.some(member => member.name.toLowerCase().includes(query))
        );
      });
    }

    // Apply Not Applied filter
    const notAppliedFilter = this.filterChips.find(c => c.type === 'notApplied');
    if (notAppliedFilter?.active) {
      jobs = jobs.filter(job => !job.applied);
    }

    // Apply Not Easy Apply filter
    const notEasyApplyFilter = this.filterChips.find(c => c.type === 'notEasyApply');
    if (notEasyApplyFilter?.active) {
      jobs = jobs.filter(job => !job.easy_apply);
    }

    // Apply Not Clicked filter
    const notClickedFilter = this.filterChips.find(c => c.type === 'notClicked');
    if (notClickedFilter?.active) {
      jobs = jobs.filter(job => {
        // Only filter jobs that have external links
        if (!job.external_link) return true;
        
        const key = this.generateJobKey(job);
        const clicked = localStorage.getItem(key);
        return !clicked;
      });
    }

    // Apply Hide Not Applicable filter
    const notApplicableFilter = this.filterChips.find(c => c.type === 'notApplicable');
    if (notApplicableFilter?.active) {
      jobs = jobs.filter(job => !this.isNotApplicable(job));
    }

    // Apply location filters (OR logic)
    const activeLocationFilters = this.locationChips.filter(c => c.active);
    if (activeLocationFilters.length > 0) {
      jobs = jobs.filter(job => 
        activeLocationFilters.some(filter => 
          job.location.toLowerCase().includes(filter.value!.toLowerCase())
        )
      );
    }

    // Apply past 24 hours filter
    const past24HoursFilter = this.filterChips.find(c => c.type === 'past24Hours');
    if (past24HoursFilter?.active) {
      jobs = jobs.filter(job => this.isWithinPast24Hours(job.posted_time));
    }

    // Apply sort by time
    const sortByTimeFilter = this.filterChips.find(c => c.type === 'sortByTime');
    if (sortByTimeFilter?.active) {
      jobs.sort((a, b) => this.parseTimeToMinutes(a.posted_time) - this.parseTimeToMinutes(b.posted_time));
    }

    this.filteredJobs = jobs;
    
    // Clear selection if filtered job is not in the list
    if (this.selectedJob && !this.filteredJobs.includes(this.selectedJob)) {
      this.selectedJob = null;
    }
  }

  parseTimeToMinutes(timeStr: string): number {
    const cleaned = timeStr.toLowerCase().replace('reposted', '').trim();
    
    const minuteMatch = cleaned.match(/(\d+)\s*minute/);
    if (minuteMatch) return parseInt(minuteMatch[1]);

    const hourMatch = cleaned.match(/(\d+)\s*hour/);
    if (hourMatch) return parseInt(hourMatch[1]) * 60;

    const dayMatch = cleaned.match(/(\d+)\s*day/);
    if (dayMatch) return parseInt(dayMatch[1]) * 1440;

    const weekMatch = cleaned.match(/(\d+)\s*week/);
    if (weekMatch) return parseInt(weekMatch[1]) * 10080;

    const monthMatch = cleaned.match(/(\d+)\s*month/);
    if (monthMatch) return parseInt(monthMatch[1]) * 43200;

    return 999999; // Unknown time format goes to end
  }

  isWithinPast24Hours(timeStr: string): boolean {
    const minutes = this.parseTimeToMinutes(timeStr);
    return minutes <= 1440; // 24 hours = 1440 minutes
  }

  selectJob(job: Job): void {
    this.selectedJob = job;
  }

  formatJobDescription(description: string): string {
    if (!description) return '';
    
    // Convert newlines to <br> tags
    return description
      .replace(/\n\n/g, '</p><p>')
      .replace(/\n/g, '<br>')
      .replace(/^/, '<p>')
      .replace(/$/, '</p>');
  }

  generateJobKey(job: Job): string {
    // Create a unique key combining job title, company name, and location
    return `job_${job.job_title}_${job.company_name}_${job.location}`
      .replace(/\s+/g, '_')
      .replace(/[^a-zA-Z0-9_]/g, '')
      .toLowerCase();
  }

  onExternalApplicationClick(job: Job, event: Event): void {
    event.preventDefault();
    
    const key = this.generateJobKey(job);
    const clickData = {
      jobTitle: job.job_title,
      companyName: job.company_name,
      location: job.location,
      clickedDate: new Date().toISOString()
    };
    
    localStorage.setItem(key, JSON.stringify(clickData));
    
    // Open the external link
    window.open(job.external_link!, '_blank', 'noopener,noreferrer');
    
    // Keep the job selected and update the view
    const jobIndex = this.filteredJobs.findIndex(j => j === this.selectedJob);
    if (jobIndex !== -1) {
      // Force change detection by creating a new reference
      this.filteredJobs = [...this.filteredJobs];
      this.selectedJob = this.filteredJobs[jobIndex];
    }
  }

  getClickedDate(job: Job): string | null {
    const key = this.generateJobKey(job);
    const stored = localStorage.getItem(key);
    
    if (!stored) return null;
    
    try {
      const data = JSON.parse(stored);
      const clickedDate = new Date(data.clickedDate);
      return this.formatClickedDate(clickedDate);
    } catch (e) {
      return null;
    }
  }

  formatClickedDate(date: Date): string {
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    
    if (diffDays === 0) {
      return 'today';
    } else if (diffDays === 1) {
      return 'yesterday';
    } else if (diffDays < 7) {
      return `${diffDays} days ago`;
    } else {
      // Format as MM/DD/YYYY
      const month = date.getMonth() + 1;
      const day = date.getDate();
      const year = date.getFullYear();
      return `${month}/${day}/${year}`;
    }
  }

  getJobKeywords(job: Job): string[] {
    if (!job.job_description) return [];
    
    const description = job.job_description.toLowerCase();
    const keywords: string[] = [];
    
    if (description.includes('b2b')) {
      keywords.push('B2B');
    }
    if (description.includes('saas')) {
      keywords.push('SaaS');
    }
    if (description.includes('b2c')) {
      keywords.push('B2C');
    }
    
    return keywords;
  }

  generateNotApplicableKey(job: Job): string {
    // Create a unique key for not applicable status
    return `not_applicable_${job.job_title}_${job.company_name}_${job.location}`
      .replace(/\s+/g, '_')
      .replace(/[^a-zA-Z0-9_]/g, '')
      .toLowerCase();
  }

  isNotApplicable(job: Job): boolean {
    const key = this.generateNotApplicableKey(job);
    return localStorage.getItem(key) === 'true';
  }

  isClicked(job: Job): boolean {
    if (!job.external_link) return false;
    const key = this.generateJobKey(job);
    return localStorage.getItem(key) !== null;
  }

  onNotApplicableChange(job: Job, event: Event): void {
    const checkbox = event.target as HTMLInputElement;
    const key = this.generateNotApplicableKey(job);
    
    if (checkbox.checked) {
      localStorage.setItem(key, 'true');
    } else {
      localStorage.removeItem(key);
    }
    
    // Force update of the job list to show/hide the "Not Applicable" badge
    const jobIndex = this.filteredJobs.findIndex(j => j === this.selectedJob);
    if (jobIndex !== -1) {
      this.filteredJobs = [...this.filteredJobs];
      this.selectedJob = this.filteredJobs[jobIndex];
    }
  }
}
