  @HostListener('window:keydown', ['$event'])
  handleKeyDown(event: KeyboardEvent) {
    if (event.key === 'Escape') {
      this.closePopup();
    } else if (event.key === 'ArrowUp') {
      if (this.showPopup) {
        event.preventDefault();
        let index = StocksConstants.all_rows.findIndex(x => x.tradingsymbol === this.popupChart2.tradingsymbol && x.index === this.popupChart2.index);
        if (index > 0) {
          const previousItem = StocksConstants.all_rows[index - 1];
          console.log('Previous object:', previousItem);
          this.openPopup(previousItem);
        } else {
          console.log('No previous item found or target is at the start.');
        }
      }
    } else if (event.key === 'ArrowDown') {
      if (this.showPopup) {
        event.preventDefault();
        let index = StocksConstants.all_rows.findIndex(x => x.tradingsymbol === this.popupChart2.tradingsymbol && x.index === this.popupChart2.index);
        if (index >= 0 && index < StocksConstants.all_rows.length - 1) {
          const nextItem = StocksConstants.all_rows[index + 1];
          console.log('Next object:', nextItem);
          this.openPopup(nextItem);
        } else {
          console.log('No next item found or target is at the end.');
        }
      }
    }
  }

