  addToWatchlist(element: StockData) {
    if (!StocksConstants.watchlist.includes(element.tradingsymbol)) {
      StocksConstants.watchlist.push(element.tradingsymbol);
      this.saveWatchlistToLS();
      let arr: StockData[] = StocksConstants.all_rows.filter(x => x.tradingsymbol === element.tradingsymbol);
      for (let k = 0; k < arr.length; k++) {
        let e = arr[k];
        e.watchlist = true;
      }
      //this.stocksService.sortByReturns();
    }
  }

  countWatchlist() {
    let count = 0;
    let arr: StockData[] = StocksConstants.all_rows.filter(x => x.index === 'NIFTY 500' && !x.isIndex);
    for (let k = 0; k < arr.length; k++) {
      let e = arr[k];
      if (e.watchlist) {
        count++;
      }
    }
    return count;
  }

  removeFromWatchlist(element: StockData) {
    let index = StocksConstants.watchlist.indexOf(element.tradingsymbol);
    if (index > -1) { // only splice array when item is found
      StocksConstants.watchlist.splice(index, 1); // 2nd parameter means remove one item only
    }
    this.saveWatchlistToLS();
    let arr: StockData[] = StocksConstants.all_rows.filter(x => x.tradingsymbol === element.tradingsymbol);
    for (let k = 0; k < arr.length; k++) {
      let e = arr[k];
      e.watchlist = false;
    }
    //this.stocksService.sortByReturns();
  }

  saveWatchlistToLS() {
    localStorage.setItem('stocks_watchlist', JSON.stringify(StocksConstants.watchlist));
  }

  loadWatchlistFromLS() {
    StocksConstants.watchlist = JSON.parse(localStorage.getItem('stocks_watchlist'));
    if (StocksConstants.watchlist === null) {
      StocksConstants.watchlist = [];
    }
  }

  exportWatchlist() {
    let export_file_name = 'watchlist.csv';
    console.log('exporting: ', export_file_name);

    let str = '';
    StocksConstants.watchlist.forEach(w => {
      str += w + '\r\n';
    });

    const downloadFile = new Blob([str], {
      type: 'application/x-msdownload',
    });
    const fileURL = URL.createObjectURL(downloadFile);
    const link = document.createElement('a');
    link.href = fileURL;
    link.target = '_blank';
    document.body.appendChild(link);
    link.download = export_file_name;
    link.click();
    link.parentNode.removeChild(link);
  }

