import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable, from, of, timer } from 'rxjs';
import { concatMap, map, catchError } from 'rxjs/operators';

// ─────────────────────────────────────────────
// Public interfaces
// ─────────────────────────────────────────────

export interface NewsItem {
  title: string;
  url: string;
  source: string;
  datetime: string;   // ISO 8601 string
  timestamp: number;  // epoch ms
}

export interface SymbolInfo {
  scrip: string;
  exchange: string;
}

export interface SymbolNewsResult {
  symbol: string;
  news: NewsItem[];
}

// ─────────────────────────────────────────────
// Finnhub raw response shape
// ─────────────────────────────────────────────

interface FinnhubNewsItem {
  category: string;
  datetime: number;   // epoch seconds
  headline: string;
  id: number;
  image: string;
  related: string;
  source: string;
  summary: string;
  url: string;
}

// ─────────────────────────────────────────────
// Module-level constants
// ─────────────────────────────────────────────

const FINNHUB_BASE_URL = 'https://finnhub.io/api/v1';

/**
 * Minimum milliseconds between consecutive API calls.
 * Finnhub free tier: 60 req/min → 1 000 ms safe minimum.
 * Raise to 1 100+ ms if rate-limit errors appear.
 * Free paid tiers can lower this to 300–400 ms.
 */
const REQUEST_DELAY_MS = 1_100;

const MAX_NEWS_PER_SYMBOL = 12;

const INDIAN_EXCHANGES = new Set(['NSE', 'BSE', 'NFO', 'CDS', 'MCX', 'BFO']);

// ─────────────────────────────────────────────
// Exported pure helpers (importable by tests)
// ─────────────────────────────────────────────

/**
 * Converts a raw scrip + exchange pair into the symbol string
 * expected by the Finnhub company-news endpoint.
 *
 * Indian exchanges  → "NSE:WOCKPHARMA"
 * US / other        → "AAPL"
 */
export function normalizeSymbolForFinnhub(scrip: string, exchange: string): string {
  const ex = (exchange ?? '').trim().toUpperCase();
  const sym = scrip.trim().toUpperCase();
  return INDIAN_EXCHANGES.has(ex) ? `NSE:${sym}` : sym;
}

function toYYYYMMDD(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

function mapFinnhubItem(raw: FinnhubNewsItem): NewsItem {
  return {
    title:     raw.headline,
    url:       raw.url,
    source:    raw.source,
    datetime:  new Date(raw.datetime * 1_000).toISOString(),
    timestamp: raw.datetime * 1_000,
  };
}

function deduplicateByScript(infos: SymbolInfo[]): SymbolInfo[] {
  const seen = new Set<string>();
  return infos.filter(({ scrip }) => {
    const key = scrip.trim().toUpperCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

// ─────────────────────────────────────────────
// Service
// ─────────────────────────────────────────────

@Injectable({ providedIn: 'root' })
export class StockNewsService {

  private readonly apiKey: string = 'd7l2u2pr01qm7o0aabogd7l2u2pr01qm7o0aabp0';

  constructor(private readonly http: HttpClient) {}

  // ── Public API ────────────────────────────

  /**
   * Fetches news for a single, already-normalised symbol.
   * Sorts descending by timestamp; trims to MAX_NEWS_PER_SYMBOL.
   * Never throws – returns [] on error.
   */
  fetchNewsForSymbol(
    symbol: string,
    fromDate: string,
    toDate: string,
  ): Observable<NewsItem[]> {

    const params = new HttpParams()
      .set('symbol',  symbol)
      .set('from',    fromDate)
      .set('to',      toDate)
      .set('token',   this.apiKey);

    return this.http
      .get<FinnhubNewsItem[]>(`${FINNHUB_BASE_URL}/company-news`, { params })
      .pipe(
        map((items: FinnhubNewsItem[]) =>
          (Array.isArray(items) ? items : [])
            .map(mapFinnhubItem)
            .sort((a, b) => b.timestamp - a.timestamp)
            .slice(0, MAX_NEWS_PER_SYMBOL),
        ),
        catchError((err: unknown) => {
          console.error(`[StockNewsService] news fetch failed for "${symbol}":`, err);
          return of<NewsItem[]>([]);
        }),
      );
  }

  /**
   * Sequentially fetches news for every unique scrip in `symbolInfos`.
   * Emits one SymbolNewsResult per symbol as each completes.
   * A fixed REQUEST_DELAY_MS gap is injected before each HTTP call
   * to respect Finnhub rate limits.
   *
   * Date window: today → tomorrow (captures full trading day).
   */
  fetchNewsForSymbols(symbolInfos: SymbolInfo[]): Observable<SymbolNewsResult> {
    const unique = deduplicateByScript(symbolInfos);

    if (!unique.length) {
      return new Observable<SymbolNewsResult>(subscriber => subscriber.complete());
    }

    const today    = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);

    const fromDate = toYYYYMMDD(today);
    const toDate   = toYYYYMMDD(tomorrow);

    return from(unique).pipe(
      concatMap((info: SymbolInfo) => {
        const normalised = normalizeSymbolForFinnhub(info.scrip, info.exchange);

        /*
         * timer(REQUEST_DELAY_MS) introduces a mandatory pause before each
         * HTTP call, then inner concatMap executes the request.
         * Because the outer concatMap is sequential, the effective cadence is:
         *   delay → request → response → delay → request → …
         * This guarantees we never fire two requests within REQUEST_DELAY_MS.
         */
        return timer(REQUEST_DELAY_MS).pipe(
          concatMap(() =>
            this.fetchNewsForSymbol(normalised, fromDate, toDate).pipe(
              map((news): SymbolNewsResult => ({ symbol: info.scrip, news })),
            ),
          ),
        );
      }),
    );
  }
}