  /*
  The monthlyExpiryDates* maps below are auto-topped-up from the Zerodha masters contract on every
  fetch/import - see ZerodhaService.collectMonthlyExpiry(). Only MISSING keys are added; a key that
  already exists here always wins, so nothing hand-entered is ever overwritten or removed.

  If the exchange later MOVES an expiry that is already hardcoded here (holiday shift, calendar
  change), the hardcoded value would then be wrong and the live one right. That case is not silently
  applied - it is logged as a mismatch and raised as a warning alert, so it can be corrected here by
  hand. Set overwriteMonthlyExpiriesFromMasters to true to let the live masters win instead.
  */
  static overwriteMonthlyExpiriesFromMasters = false;

  // Returns the live map object for an instrument (or null if it has none), so callers can add to it.
  static getMonthlyExpiryMap(instru: string) {
    if (instru === 'NIFTY') {
      return AppConstants.monthlyExpiryDates;
    } else if (instru === 'BANKNIFTY') {
      return AppConstants.monthlyExpiryDatesBNF;
    } else if (instru === 'FINNIFTY') {
      return AppConstants.monthlyExpiryDatesFINNIFTY;
    } else if (instru === 'MIDCPNIFTY') {
      return AppConstants.monthlyExpiryDatesMidcap;
    } else if (instru === 'SENSEX') {
      return AppConstants.monthlyExpiryDatesSensex;
    } else if (instru === 'BANKEX') {
      return AppConstants.monthlyExpiryDatesBankex;
    }
    return null;
  }

