  isMatchingFilterCriteria(item: any, filterCriteria: any): boolean {
    for (let key in filterCriteria) {
      if (!filterCriteria[key].selected) continue; // Skip if not selected

      const filterType = filterCriteria[key].type;

      if (filterType === 'non-value' && key === 'DMA200') {
        if (item['DMA200'] > item.ltp) return false; // Special condition for 'DMA200'
      }

      if (filterType === 'value') {
        // General condition for value-based filters
        if (item[key] <= filterCriteria[key].value) return false;
      }

      if (filterType === 'index') {
        // This is an index filter - check if stock is in the specified index
        if (!this.isStockInIndex(key, item.tradingsymbol)) return false;
      }
    }

    return true; // Return true only if all checks pass
  }

  isStockInIndex(index, stock) {
    return StocksConstants.stocksList.find(item => item.tradingsymbol === index)?.stocks.includes(stock) || false;
  }

  sortStocks(stocksInIndex, columnSortKey) {
    return stocksInIndex.sort((a, b) => {
      if (b.isMatchingFilter !== a.isMatchingFilter) {
        return b.isMatchingFilter ? 1 : -1; // Move matching items to the top
      }
      
      return b[columnSortKey] - a[columnSortKey]; // Sort by columnSortKey if both have the same filter match status
    });
  }

